{
     "title": "CSCI-320: Principles of Data Management",
     "learningObjectives": [
       "Define the core components of the relational database model, including entities, attributes, and relationships.",
       "Explain how Structured Query Language (SQL) is used to retrieve, update, and manage relational data.",
       "Apply data quality, transaction integrity, and security principles to design a secure relational database system."
     ],
     "beats": [
       {
         "title": "Introduction to Data Management",
         "claim": "Modern data management focuses on organizing, storing, and retrieving information efficiently using structured models.",
         "example": "A hospital system uses a relational database to link patient records, medical history, and appointment schedules.",
         "visualDirection": "Display a simple flowchart showing data flowing from collection to structured storage and retrieval.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Relational Model Foundations",
         "claim": "The relational model organizes data into tables with rows and columns, where each column represents an attribute and each row represents a record.",
         "example": "An 'Employees' table contains columns for EmployeeID, Name, Department, and Salary.",
         "visualDirection": "Show a basic table layout with labeled rows and columns, highlighting the entity-attribute relationship.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Data Modeling Concepts",
         "claim": "Data modeling involves defining entities, attributes, and relationships to accurately represent real-world scenarios in a database.",
         "example": "A 'Student' entity relates to a 'Course' entity through an 'Enrollment' relationship, linking student IDs to course codes.",
         "visualDirection": "Draw a simple ER diagram with Student, Course, and Enrollment boxes and lines connecting them.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Relational Algebra Basics",
         "claim": "Relational algebra provides a set of operations to manipulate relational data, such as selection, projection, and join.",
         "example": "A selection operation filters the 'Employees' table to show only those in the 'Engineering' department.",
         "visualDirection": "Illustrate a before-and-after table showing rows filtered by a condition using selection notation.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Structured Query Language (SQL)",
         "claim": "SQL is a standard language used to query, update, and manage relational databases through declarative statements.",
         "example": "The command SELECT * FROM Employees WHERE Department = 'Marketing' retrieves specific records.",
         "visualDirection": "Display a code snippet of the SQL query alongside the resulting filtered table output.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Data Quality Principles",
         "claim": "Data quality ensures information is accurate, complete, consistent, and timely to support reliable decision-making.",
         "example": "Validating that all 'PhoneNumber' fields follow a standard format prevents duplicate or corrupted contact records.",
         "visualDirection": "Show a checklist graphic with icons for accuracy, completeness, consistency, and timeliness.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Transaction Integrity",
         "claim": "Transaction integrity maintains database consistency through atomicity, consistency, isolation, and durability (ACID) properties.",
         "example": "A banking transaction updates both account balances atomically, ensuring neither account is left in an inconsistent state.",
         "visualDirection": "Create a step-by-step diagram showing a transaction process with ACID checkpoints at each stage.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Database Security Practices",
         "claim": "Database security protects data through encryption, access controls, and authentication to prevent unauthorized access.",
         "example": "Role-based access control limits 'view' permissions to analysts while restricting 'delete' permissions to administrators.",
         "visualDirection": "Display a permission matrix table showing user roles and their corresponding database actions.",
         "sourceIds": ["rit-csci-320", "nist-ssdf"]
       },
       {
         "title": "Application Development Approaches",
         "claim": "Building relational database application programs involves integrating SQL queries with application logic to automate data workflows.",
         "example": "An e-commerce platform uses SQL to fetch product inventory and application code to process checkout orders.",
         "visualDirection": "Sketch a simple architecture diagram with a frontend app, backend logic, and relational database connected by SQL calls.",
         "sourceIds": ["rit-csci-320"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Evaluating a relational database system requires verifying data modeling accuracy, SQL query efficiency, integrity constraints, and security configurations.",
         "example": "A developer checks that foreign keys enforce referential integrity, indexes optimize query performance, and encryption protects sensitive fields.",
         "visualDirection": "Present a printable checklist graphic with checkboxes for modeling, querying, integrity, and security verification.",
         "sourceIds": ["rit-csci-320", "nist-ssdf"]
       }
     ]
   }
